/// Reproduces `MAGIC_GET_SRC`.
pub(super) fn magic_get() -> Vec<Stmt> {
    let is = |name: &str| e_binop(e_var("name"), BinOp::StrictEq, e_str(name));
    let answer = |name: &str, value: Expr| s_if(is(name), vec![s_return(value)], vec![], None);
    vec![
        answer("start", e_method_call(e_this(), "getStartDate", vec![])),
        answer("end", e_method_call(e_this(), "getEndDate", vec![])),
        answer("interval", e_method_call(e_this(), "getDateInterval", vec![])),
        answer(
            "recurrences",
            e_binop(
                e_binop(
                    e_binop(e_this_prop("recurrenceCount"), BinOp::Add, e_int(1)),
                    BinOp::Sub,
                    e_this_prop("excludeStart"),
                ),
                BinOp::Add,
                e_ternary(e_this_prop("includeEnd"), e_int(1), e_int(0)),
            ),
        ),
        answer("include_start_date", e_binop(e_this_prop("excludeStart"), BinOp::StrictEq, e_int(0))),
        answer("include_end_date", e_binop(e_this_prop("includeEnd"), BinOp::StrictNotEq, e_int(0))),
        answer(
            "current",
            e_ternary(e_this_prop("started"), e_method_call(e_this(), "current", vec![]), e_null()),
        ),
        s_return(e_null()),
    ]
}

